mapper.select:
SELECT id, title, cover_image AS coverImage, created_at AS createdAt, shoot_date AS shootDate,
       camera_brand AS cameraBrand, camera_model AS cameraModel, is_film AS isFilm, film_stock AS filmStock
FROM album WHERE id = #{id}

mapper.update:
UPDATE album SET title = #{title}, cover_image = #{coverImage}, shoot_date = #{shootDate},
                 camera_brand = #{cameraBrand},
                 camera_model = #{cameraModel},
                 is_film = #{isFilm, jdbcType=BOOLEAN},
                 film_stock = #{filmStock}
WHERE id = #{id}
